frequency.compute_fn:
def compute(t, x):
    if len(x) < 2:
        return 0.0
    signs = np.sign(x)
    crossings = int(np.sum(signs[1:] * signs[:-1] < 0))
    T = float(t[-1] - t[0]) if float(t[-1] - t[0]) > 0 else 1.0
    return crossings / (2.0 * T)

amplitude.compute_fn:
def compute(t, x):
    if len(x) == 0:
        return 0.0
    return float((np.max(x) - np.min(x)) / 2.0)
